    @EventHandler( payloadType=UpdateEvidenceEvent.class )
    public void handle( UpdateEvidenceEvent event) {
    	LOGGER.info("handling UpdateEvidenceEvent - " + event );
    	
	    Evidence entity = new Evidence();
            entity.setEvidenceId( event.getEvidenceId() );
            entity.setTitle( event.getTitle() );
            entity.setLocationUrl( event.getLocationUrl() );
            entity.setReceivedDate( event.getReceivedDate() );
            entity.setControlTest( event.getControlTest() );
            entity.setControl( event.getControl() );
            entity.setObligation( event.getObligation() );
            entity.setWorkpaper( event.getWorkpaper() );
            entity.setEvidenceType( event.getEvidenceType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindEvidence( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllEvidence( entity );        
    }
    
