    /**
     * Method to retrieve the Evidence via an EvidencePrimaryKey.
     * @param 	id Long
     * @return 	Evidence
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Evidence handle( FindEvidenceQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getEvidenceId() );
    }
    
    /**
     * Method to retrieve a collection of all Evidences
     *
     * @param	query	FindAllEvidenceQuery 
     * @return 	List<Evidence> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Evidence> handle( FindAllEvidenceQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindEvidence,
 * but only if the id matches
 *
 * @param		entity	Evidence
 */
	protected void emitFindEvidence( Evidence entity ) {
		LOGGER.info("handling emitFindEvidence" );
		
	    queryUpdateEmitter.emit(FindEvidenceQuery.class,
	                            query -> query.getFilter().getEvidenceId().equals(entity.getEvidenceId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllEvidence
	 * 
	 * @param		entity	Evidence
	 */
	protected void emitFindAllEvidence( Evidence entity ) {
		LOGGER.info("handling emitFindAllEvidence" );
		
	    queryUpdateEmitter.emit(FindAllEvidenceQuery.class,
	                            query -> true,
	                            entity);
	}

